import {
  GET_DOGS,
  GET_TEMPERAMENTS,
  GET_DETAIL,
  GET_BY_NAME,
  ORDER_BY,
  CLEAN,
  GET_BY_TEMPERAMENTS,
  FILTER_BY,
  CHARGE_ALL,
  PAGINATE,
  FILTER_TEMPERAMENT,
} from "../actions/index";

const initialState = {
  dogs: [],
  temperaments: [],
  filtered: 'LOADING...',
  dogDetail: {},
  currentPage: 1,
};

function rootReducer(state = initialState, action) {
  switch (action.type) {
    case GET_DOGS:
      return {
        ...state,
        dogs: action.payload,
        filtered: action.payload,
      };
    case GET_TEMPERAMENTS:
      return {
        ...state,
        temperaments: action.payload,
      };
    case CLEAN:
      return {
        ...state,
        dogDetail: {},
      };

    case GET_DETAIL:
      return {
        ...state,
        dogDetail: action.payload,
      };

    case GET_BY_NAME:
        return {
          ...state,
          dogs: action.payload,
        }

    case GET_BY_TEMPERAMENTS:
      return {
        ...state,
       temperaments: action.payload,
        }

    case CHARGE_ALL:
      return { ...state, filtered: state.dogs };

    case FILTER_BY:
      if (action.payload === "DB") {
        let data = state.dogs.filter((item) => typeof item.id === "string")
        if(data.length <= 0){
          return {
            ...state,
            filtered: 'NO_BREEDS'
          }
        } else
        return {
          ...state,
          filtered: data
        };
      } else {
        return {
          ...state,
          filtered: state.dogs.filter((item) => typeof item.id === "number"),
        };
      }
      case FILTER_TEMPERAMENT:
        let allTemperaments = [...state.breedsClean]
        //if(action.payload === 'All Temperaments') return {...state, breeds: state.breeds}
        let aux2 = action.payload === 'All Temperaments' ? allTemperaments : allTemperaments.filter(el => el.temperament.includes(action.payload))
        console.log(aux2)                
        return {
            ...state,
            breeds: aux2
        } 
        case ORDER_BY:
          let orderAz = [...state.breeds]
          orderAz = orderAz.sort((a, b) => {
              switch(action.payload){
                  case A_Z:
                      if(a.name < b.name) {
                          return -1;
                      } else return 1
                  case Z_A:
                      if(a.name > b.name) {
                          return -1;
                      } else return 1
                  case WEIGHT_MAX:
                      if(a.weightMax > b.weightMax) {
                          return -1
                      } else return 1
                  case WEIGHT_MIN:
                      if(a.weightMin < b.weightMin) {
                          return -1
                      } else return 1
                  default: return 0;
                  }  
          })
      case PAGINATE: 
      return{
       ...state, 
       currentPage: action.payload
      }

    default:
      return state;
  }
}

export default rootReducer;
